import Foundation

struct RepStateMachine {
    private var currentState: Bool = false
    private var consecutiveFramesInState: Int = 0

    init(enterThreshold: Double, exitThreshold: Double, minDwellFrames: Int) {
        // Initialize thresholds and dwell frames
    }

    mutating func update(measurement: Double) -> RepStateTransition? {
        let inTargetRange = measurement >= enterThreshold && measurement <= exitThreshold
        if consecutiveFramesInState == 0 {
            currentState = inTargetRange
        }

        consecutiveFramesInState += 1
        if inTargetRange != currentState {
            currentState = inTargetRange
            consecutiveFramesInState = 0
        }

        if consecutiveFramesInState >= minDwellFrames {
            let transition: RepStateTransition = inTargetRange ? .enteredBottom : .exitedBottom(reachedDepth: true)
            consecutiveFramesInState = 0
            return transition
        }

        return nil
    }
}

enum RepStateTransition {
    case enteredBottom, exitedBottom(reachedDepth: Bool)
}
